class Solution {
public:
    int longestSubsequence(vector<int>& nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = max(maxVal, x);
        vector<vector<int>> dp(maxVal + 1, vector<int>(maxVal + 1, 0));
        int ans = 1;

        for (int x : nums) {
            vector<int> bestLen(maxVal + 1, 1);
            for (int prevV = 1; prevV <= maxVal; ++prevV) {
                int d = abs(x - prevV);
                bestLen[d] = max(bestLen[d], 1 + dp[prevV][d]);
            }
            int currMax = 0;
            for (int d = maxVal; d >= 0; --d) {
                currMax = max(currMax, bestLen[d]);
                bestLen[d] = currMax;
            }
            for (int d = 0; d <= maxVal; ++d) {
                dp[x][d] = max(dp[x][d], bestLen[d]);
                ans = max(ans, dp[x][d]);
            }
        }
        return ans;
    }
};

class Solution {
    public int longestSubsequence(int[] nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);
        int[][] dp = new int[maxVal + 1][maxVal + 1];
        int ans = 1;

        for (int x : nums) {
            int[] bestLen = new int[maxVal + 1];
            Arrays.fill(bestLen, 1);
            for (int prevV = 1; prevV <= maxVal; ++prevV) {
                int d = Math.abs(x - prevV);
                bestLen[d] = Math.max(bestLen[d], 1 + dp[prevV][d]);
            }
            int currMax = 0;
            for (int d = maxVal; d >= 0; --d) {
                currMax = Math.max(currMax, bestLen[d]);
                bestLen[d] = currMax;
            }
            for (int d = 0; d <= maxVal; ++d) {
                dp[x][d] = Math.max(dp[x][d], bestLen[d]);
                ans = Math.max(ans, dp[x][d]);
            }
        }
        return ans;
    }
}

var longestSubsequence = function(nums) {
    let maxVal = 0;
    for (const x of nums) maxVal = Math.max(maxVal, x);
    const dp = Array.from({ length: maxVal + 1 }, () => new Int32Array(maxVal + 1));
    let ans = 1;

    for (const x of nums) {
        const bestLen = new Int32Array(maxVal + 1);
        bestLen.fill(1);
        for (let prevV = 1; prevV <= maxVal; ++prevV) {
            const d = Math.abs(x - prevV);
            bestLen[d] = Math.max(bestLen[d], 1 + dp[prevV][d]);
        }
        let currMax = 0;
        for (let d = maxVal; d >= 0; --d) {
            currMax = Math.max(currMax, bestLen[d]);
            bestLen[d] = currMax;
        }
        for (let d = 0; d <= maxVal; ++d) {
            dp[x][d] = Math.max(dp[x][d], bestLen[d]);
            ans = Math.max(ans, dp[x][d]);
        }
    }
    return ans;
};
